public class InnerDataSourceManagedKnowledgeBaseConnectorConfigurationFactory(Action<Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration>
{

    internal InnerDataSourceSyncScheduleFactory SyncScheduleFactory { get; set; }

    internal InnerDataSourceMediaExtractionConfigurationFactory MediaExtractionConfigurationFactory { get; set; }

    internal InnerDataSourceDeletionProtectionConfigurationFactory DeletionProtectionConfigurationFactory { get; set; }

    protected override Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration Create()
    {
        var managedKnowledgeBaseConnectorConfigurationResult = CreateManagedKnowledgeBaseConnectorConfiguration();
        factoryAction?.Invoke(managedKnowledgeBaseConnectorConfigurationResult);

        return managedKnowledgeBaseConnectorConfigurationResult;
    }

    private Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration CreateManagedKnowledgeBaseConnectorConfiguration()
    {
        var managedKnowledgeBaseConnectorConfigurationResult = new Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration();

        return managedKnowledgeBaseConnectorConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataSourceTypes.ManagedKnowledgeBaseConnectorConfiguration result)
    {
        base.CreateChildren(result);

        result.SyncSchedule ??= SyncScheduleFactory?.Build();
        result.MediaExtractionConfiguration ??= MediaExtractionConfigurationFactory?.Build();
        result.DeletionProtectionConfiguration ??= DeletionProtectionConfigurationFactory?.Build();
    }

} // End Of Class

